Idea
- Write any integer n as n = 2^a × s where s is odd.
- n is remarkable iff a ≥ 1 and s is a perfect square (s = r^2 with r odd).
- For each a ≥ 1, count odd r with r^2 ≤ M / 2^a. If R_a = floor(sqrt(M / 2^a)), the count is (R_a + 1) // 2.
- Sum this over all a until M / 2^a = 0.

This avoids double counting because fixing a (and r odd) fixes v2(n) exactly.

C++17 implementation (works up to M ≤ 1e18):

```cpp
#include <bits/stdc++.h>
using namespace std;

// Integer floor square root for 0 <= n <= 1e18
static inline unsigned long long isqrt_ull(unsigned long long n) {
    unsigned long long l = 0, r = 1;
    while ((__int128)r * r <= n) r <<= 1;  // find an upper bound
    while (r - l > 1) {
        unsigned long long m = l + (r - l) / 2;
        if ((__int128)m * m <= n) l = m;
        else r = m;
    }
    return l;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long M;
    if (!(cin >> M)) return 0;

    unsigned long long ans = 0;
    unsigned long long x = M >> 1;  // x = floor(M / 2^a) with a = 1 initially
    while (x > 0) {
        unsigned long long R = isqrt_ull(x);
        ans += (R + 1) / 2;  // count of odd r <= R
        x >>= 1;             // divide by 2: advance to next a
    }

    cout << ans << '\n';
    return 0;
}
```

The loop runs for at most about 60 iterations; each integer sqrt is O(log M), so it’s very fast.

Solution idea:
- For any fixed length L ≥ 2 and leading digit d (1..9), a number is Peak iff every other digit is in [0, d−1]. Thus there are d^(L−1) such numbers.
- To count Peak numbers ≤ N, add:
  - All counts for lengths 2..(len(N)−1): sum over d of d^(L−1).
  - For length len(N): handle the leading digit d1:
    - For d1 < first digit of N: add d1^(L−1).
    - For d1 = first digit of N: count suffixes (length L−1) with digits in [0, d1−1] that are lexicographically ≤ N’s suffix. This is a simple digit DP/greedy count.

Answer = countUpTo(B) − countUpTo(A−1).

Below is an implementation in C++17.

```cpp
#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;

ull pw[10][20]; // pw[b][e] = b^e, for b in [0..9], e in [0..19]

vector<int> digits_of(ull x) {
    string s = to_string(x);
    vector<int> d(s.size());
    for (size_t i = 0; i < s.size(); ++i) d[i] = s[i] - '0';
    return d;
}

// Count the number of sequences T of length m with each digit in [0..hi],
// such that T <= S lexicographically (S is a decimal digit vector of length m).
ull bounded_count(const vector<int>& S, int start, int m, int hi) {
    int base = hi + 1; // in [1..9]
    ull res = 0;
    for (int i = 0; i < m; ++i) {
        int s = S[start + i];
        if (s <= hi) {
            res += (ull)s * pw[base][m - 1 - i];
            // choose digit == s, stay tight
        } else {
            // all base choices here are strictly less than s, then free afterwards
            res += pw[base][m - i];
            return res;
        }
    }
    // exact match
    res += 1;
    return res;
}

ull countUpTo(ull N) {
    if (N < 10) return 0;
    vector<int> d = digits_of(N);
    int L = (int)d.size();
    ull total = 0;

    // lengths 2..L-1
    for (int len = 2; len < L; ++len) {
        for (int lead = 1; lead <= 9; ++lead) {
            total += pw[lead][len - 1];
        }
    }

    // length L
    int first = d[0];
    for (int lead = 1; lead < first; ++lead) {
        total += pw[lead][L - 1];
    }
    // lead == first
    if (first >= 1) {
        int hi = first - 1;
        total += bounded_count(d, 1, L - 1, hi);
    }

    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    // precompute powers
    for (int b = 0; b <= 9; ++b) {
        pw[b][0] = 1;
        for (int e = 1; e < 20; ++e) pw[b][e] = pw[b][e - 1] * (ull)b;
    }

    ull A, B;
    if (!(cin >> A >> B)) return 0;
    ull ans = countUpTo(B) - (A > 0 ? countUpTo(A - 1) : 0);
    cout << ans << '\n';
    return 0;
}
```

Explanation of bounded_count:
- Let base = hi + 1. Scan the suffix of N from left to right.
- While tight, at position i:
  - If S[i] ≤ hi: we can pick any digit < S[i] (S[i] choices), yielding S[i] * base^(remaining) sequences; then match S[i] and continue tight.
  - If S[i] > hi: any of the base choices is strictly less than S[i], so all base^(remaining+1) sequences are valid; we’re done.
- If all positions matched, add 1 for the exact match.

