def count_snake_leq(N: int) -> int:
    if N < 10:
        return 0

    digits = list(map(int, str(N)))
    D = len(digits)

    @lru_cache(None)
    def dfs(pos: int, tight: int, started: int, top: int, length: int) -> int:
        if pos == D:
            return 1 if (started and length >= 2) else 0

        limit = digits[pos] if tight else 9
        res = 0

        for dig in range(0, limit + 1):
            ntight = tight and (dig == limit)
            if not started:
                if dig == 0:
                    res += dfs(pos + 1, ntight, 0, 0, 0)
                else:
                    # Start the number with first digit as top
                    res += dfs(pos + 1, ntight, 1, dig, 1)
            else:
                # After starting, all following digits must be < top
                if dig < top:
                    res += dfs(pos + 1, ntight, 1, top, length + 1)
                else:
                    continue
        return res

    return dfs(0, 1, 0, 0, 0)

